function AdminSales({ ordersPage = false }: { ordersPage?: boolean }) { return <PortalShell kind="admin"><PortalHeading title={ordersPage ? "Pedidos" : "Ventas"} copy={ordersPage ? "Revisa el estado de cada compra realizada." : "Resultados comerciales de todos los eventos."} action={<Button variant="outline"><Download className="mr-2 h-4 w-4" />Exportar CSV</Button>} />{!ordersPage && <div className="mb-7 grid gap-4 sm:grid-cols-3"><MetricCard icon={TrendingUp} label="Ventas totales" value="$18.429.840" detail="Periodo seleccionado" /><MetricCard icon={Ticket} label="Transacciones" value="1.284" detail="+14% mensual" tone="sky" /><MetricCard icon={Wallet} label="Comisión promedio" value="18,6%" detail="Rendimiento saludable" tone="orange" /></div>}<section className="overflow-hidden rounded-2xl border border-zinc-200 bg-white"><div className="flex items-center justify-between border-b border-zinc-100 p-5"><div><p className="font-black">{ordersPage ? "Todos los pedidos" : "Detalle de ventas"}</p><p className="mt-1 text-sm text-zinc-500">{orders.length} registros demostrativos</p></div><button className="flex items-center gap-2 rounded-xl border border-zinc-200 px-3 py-2 text-xs font-black"><SlidersHorizontal className="h-3.5 w-3.5" />Filtrar</button></div><OrdersTable /></section></PortalShell>; }

function AdminClients() { return <PortalShell kind="admin"><PortalHeading title="Clientes" copy="Personas que han guardado sus recuerdos con Nómada Race." /><div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white"><div className="hidden grid-cols-[1.3fr_1.3fr_.7fr_.8fr_32px] gap-4 border-b border-zinc-100 bg-zinc-50 px-5 py-3 text-[10px] font-black uppercase tracking-wider text-zinc-400 md:grid"><span>Cliente</span><span>Email</span><span>Pedidos</span><span>Total gastado</span><span /></div>{clients.map(client => <div key={client.email} className="grid gap-3 border-b border-zinc-100 px-5 py-4 last:border-0 md:grid-cols-[1.3fr_1.3fr_.7fr_.8fr_32px] md:items-center md:gap-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-zinc-100 text-xs font-black">{client.name.split(" ").map(n => n[0]).join("").slice(0, 2)}</span><span className="text-sm font-black">{client.name}</span></div><span className="text-sm text-zinc-500">{client.email}</span><span className="text-sm font-bold">{client.orders}</span><span className="text-sm font-black">{client.total}</span><ChevronRight className="hidden h-4 w-4 text-zinc-400 md:block" /></div>)}</div></PortalShell>; }

